-- CWK Smart Care — database roles (generated; idempotent). Run as a superuser/owner AFTER 0001_init.sql.
-- cwk_app       : application backend (read/insert; update only mutable tables; no DELETE; no DDL)
-- cwk_migrator  : migration CLI (staging schema + inserts into public; no UPDATE of business rows)
-- cwk_reporting : read-only reporting
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'cwk_app') THEN CREATE ROLE cwk_app NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'cwk_migrator') THEN CREATE ROLE cwk_migrator NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'cwk_reporting') THEN CREATE ROLE cwk_reporting NOLOGIN; END IF;
END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO cwk_app, cwk_migrator, cwk_reporting;
GRANT SELECT, INSERT ON schools, academic_years, terms, school_calendar, periods, settings, rule_versions, schema_versions, storage_catalog, users, identity_links, user_roles, staff_assignments, invitation_records, stations, students, classes, enrollments, guardians, student_guardians, contact_endpoints, attendance_events, daily_attendance, roll_call_sessions, attendance_corrections, reconciliation_tasks, leave_requests, leave_segments, leave_revisions, leave_approvals, cases, case_events, contact_logs, appointments, attachments, attachment_links, storage_object_mappings, notifications, notification_recipients, notification_outbox, notification_attempts, acknowledgements, channel_bindings, webhook_inbox, mutation_journal, idempotency_records, audit_events, jobs, import_batches, import_errors, migration_runs, migration_checkpoints, backup_runs, change_log, report_runs, operation_metrics TO cwk_app;
GRANT UPDATE ON schools, academic_years, terms, school_calendar, periods, settings, rule_versions, storage_catalog, users, identity_links, user_roles, staff_assignments, invitation_records, stations, students, classes, enrollments, guardians, student_guardians, contact_endpoints, daily_attendance, roll_call_sessions, attendance_corrections, reconciliation_tasks, leave_requests, leave_segments, cases, appointments, attachments, attachment_links, storage_object_mappings, notification_recipients, notification_outbox, channel_bindings, webhook_inbox, mutation_journal, idempotency_records, jobs, import_batches, migration_runs, migration_checkpoints, backup_runs, report_runs TO cwk_app;
GRANT DELETE ON idempotency_records TO cwk_app;
